1	package com.maritime.platform.gateway.security.hmac;
2	
3	import com.maritime.platform.gateway.security.GatewayPrincipal;
4	import com.maritime.platform.gateway.security.GatewaySecurityProperties;
5	import com.maritime.platform.gateway.security.jwt.GatewayAuthErrorCode;
6	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationException;
7	
8	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
9	import org.springframework.stereotype.Component;
10	
11	import reactor.core.publisher.Mono;
12	
13	import javax.crypto.Mac;
14	import javax.crypto.spec.SecretKeySpec;
15	import java.nio.charset.StandardCharsets;
16	import java.security.MessageDigest;
17	import java.time.Clock;
18	import java.time.Duration;
19	import java.util.HexFormat;
20	
21	/**
22	 * Authenticates system-to-system requests using HMAC-SHA256 signatures.
23	 *
24	 * <p>Validation sequence:
25	 * <ol>
26	 *   <li>Validate timestamp is within the configured tolerance window</li>
27	 *   <li>Validate nonce length meets the configured minimum</li>
28	 *   <li>Check nonce has not been replayed via Redis SETNX</li>
29	 *   <li>Compute SHA-256 of the request body and compare with client digest (constant-time)</li>
30	 *   <li>Build the canonical request string and compute HMAC-SHA256</li>
31	 *   <li>Compare computed signature with client signature (constant-time)</li>
32	 * </ol>
33	 */
34	@Component
35	@ConditionalOnProperty("maritime.gateway.security.hmac.enabled")
36	public class HmacAuthenticationManager {
37	
38		private static final String HMAC_ALGORITHM = "HmacSHA256";
39		private static final HexFormat HEX = HexFormat.of();
40	
41		private final GatewaySecurityProperties properties;
42		private final HmacCanonicalRequestBuilder canonicalBuilder;
43		private final HmacNonceValidator nonceValidator;
44		private final Clock clock;
45	
46		public HmacAuthenticationManager(GatewaySecurityProperties properties,
47				HmacCanonicalRequestBuilder canonicalBuilder,
48				HmacNonceValidator nonceValidator) {
49			this(properties, canonicalBuilder, nonceValidator, Clock.systemUTC());
50		}
51	
52		public HmacAuthenticationManager(GatewaySecurityProperties properties,
53				HmacCanonicalRequestBuilder canonicalBuilder,
54				HmacNonceValidator nonceValidator, Clock clock) {
55			this.properties = properties;
56			this.canonicalBuilder = canonicalBuilder;
57			this.nonceValidator = nonceValidator;
58			this.clock = clock;
59		}
60	
61		/**
62		 * Authenticates an HMAC-signed request.
63		 *
64		 * @param appKey       the app key from X-App-Key header
65		 * @param timestamp    epoch millis from X-Timestamp header
66		 * @param nonce        nonce from X-Nonce header
67		 * @param clientDigest SHA-256 hex of the request body from X-Body-Digest header
68		 * @param clientSig    HMAC-SHA256 hex signature from X-Signature header
69		 * @param method       uppercase HTTP method
70		 * @param rawPath      raw URI path
71		 * @param rawQuery     raw URI query string
72		 * @param bodyBytes    the request body bytes (empty array for no body)
73		 * @return Mono of App principal on success
74		 */
75		public Mono<GatewayPrincipal.App> authenticate(String appKey, String timestamp,
76				String nonce, String clientDigest, String clientSig,
77				String method, String rawPath, String rawQuery, byte[] bodyBytes) {
78	
79			GatewaySecurityProperties.Hmac hmac = properties.getHmac();
80			Duration tolerance = hmac.getTimestampTolerance();
81			int minNonceLength = hmac.getMinNonceLength();
82	
83			// 1. Validate timestamp window
84			long ts;
85			try {
86				ts = Long.parseLong(timestamp);
87			} catch (NumberFormatException e) {
88				return Mono.error(new JwtAuthenticationException(
89						GatewayAuthErrorCode.TIMESTAMP_EXPIRED,
90						"Invalid timestamp format: " + timestamp));
91			}
92			long now = clock.millis();
93			if (Math.abs(now - ts) > tolerance.toMillis()) {
94				return Mono.error(new JwtAuthenticationException(
95						GatewayAuthErrorCode.TIMESTAMP_EXPIRED,
96						"Timestamp is outside the allowed tolerance window"));
97			}
98	
99			// 2. Validate nonce length
100			if (nonce == null || nonce.length() < minNonceLength) {
101				return Mono.error(new JwtAuthenticationException(
102						GatewayAuthErrorCode.INVALID_SIGNATURE,
103						"Nonce is too short, minimum length is " + minNonceLength));
104			}
105	
106			// 3. Compute body digest and compare
107			String computedDigest = sha256Hex(bodyBytes);
108			if (!constantTimeEquals(computedDigest, clientDigest)) {
109				return Mono.error(new JwtAuthenticationException(
110						GatewayAuthErrorCode.INVALID_SIGNATURE,
111						"Body digest does not match"));
112			}
113	
114			// 4. Validate nonce (Redis SETNX)
115			return nonceValidator.validate(appKey, nonce)
116					.then(Mono.fromCallable(() -> {
117						// 5. Build canonical string and compute signature
118						String canonical = canonicalBuilder.build(appKey, method, rawPath,
119								rawQuery, timestamp, nonce, clientDigest);
120	
121						String appSecret = resolveAppSecret(appKey);
122						if (appSecret == null) {
123							throw new JwtAuthenticationException(
124									GatewayAuthErrorCode.INVALID_SIGNATURE,
125									"Unknown app key: " + appKey);
126						}
127	
128						String computedSig = hmacSha256Hex(appSecret, canonical);
129						if (!constantTimeEquals(computedSig, clientSig)) {
130							throw new JwtAuthenticationException(
131									GatewayAuthErrorCode.INVALID_SIGNATURE,
132									"Signature does not match");
133						}
134	
135						String appCode = resolveAppCode(appKey);
136						return new GatewayPrincipal.App(appKey, appCode != null ? appCode : appKey);
137					}));
138		}
139	
140		private String resolveAppSecret(String appKey) {
141			for (GatewaySecurityProperties.ConfigApp app : properties.getHmac().getCredentials().getApps()) {
142				if (app.getAppKey().equals(appKey) && app.isEnabled()) {
143					return app.getAppSecret();
144				}
145			}
146			return null;
147		}
148	
149		private String resolveAppCode(String appKey) {
150			for (GatewaySecurityProperties.ConfigApp app : properties.getHmac().getCredentials().getApps()) {
151				if (app.getAppKey().equals(appKey)) {
152					return app.getAppCode();
153				}
154			}
155			return null;
156		}
157	
158		static String sha256Hex(byte[] data) {
159			try {
160				return HEX.formatHex(MessageDigest.getInstance("SHA-256").digest(data));
161			} catch (java.security.NoSuchAlgorithmException e) {
162				throw new RuntimeException("SHA-256 algorithm not available", e);
163			}
164		}
165	
166		static String hmacSha256Hex(String key, String data) {
167			try {
168				Mac mac = Mac.getInstance(HMAC_ALGORITHM);
169				SecretKeySpec spec = new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8), HMAC_ALGORITHM);
170				mac.init(spec);
171				return HEX.formatHex(mac.doFinal(data.getBytes(StandardCharsets.UTF_8)));
172			} catch (java.security.NoSuchAlgorithmException | java.security.InvalidKeyException e) {
173				throw new RuntimeException("HMAC-SHA256 algorithm not available", e);
174			}
175		}
176	
177		static boolean constantTimeEquals(String a, String b) {
178			if (a == null || b == null) {
179				return a == b;
180			}
181			return MessageDigest.isEqual(
182					a.getBytes(StandardCharsets.UTF_8),
183					b.getBytes(StandardCharsets.UTF_8));
184		}
185	}
