1	package com.maritime.platform.gateway.security.hmac;
2	
3	import com.maritime.platform.gateway.security.GatewaySecurityProperties;
4	import com.maritime.platform.gateway.security.jwt.GatewayAuthErrorCode;
5	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationException;
6	
7	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
8	import org.springframework.data.redis.core.ReactiveRedisOperations;
9	import org.springframework.stereotype.Component;
10	
11	import reactor.core.publisher.Mono;
12	
13	import java.time.Duration;
14	
15	/**
16	 * Validates HMAC request nonces using Redis SETNX with TTL to prevent
17	 * replay attacks on system-to-system requests.
18	 *
19	 * <p>Key format: {@code {nonceKeyPrefix}{appKey}:{nonce}}
20	 */
21	@Component
22	@ConditionalOnProperty("maritime.gateway.security.hmac.enabled")
23	public class HmacNonceValidator {
24	
25		private final ReactiveRedisOperations<String, String> redisOps;
26		private final String keyPrefix;
27		private final Duration ttl;
28	
29		public HmacNonceValidator(ReactiveRedisOperations<String, String> redisOps,
30				GatewaySecurityProperties properties) {
31			this.redisOps = redisOps;
32			GatewaySecurityProperties.Hmac hmac = properties.getHmac();
33			this.keyPrefix = hmac.getNonceKeyPrefix();
34			this.ttl = hmac.getNonceTtl();
35		}
36	
37		/**
38		 * Validate that the nonce has not been used before for this app.
39		 *
40		 * @param appKey the app key from X-App-Key header
41		 * @param nonce  the nonce value from X-Nonce header
42		 * @return empty Mono on success, error with REPLAY_DETECTED if nonce was already used
43		 */
44		public Mono<Void> validate(String appKey, String nonce) {
45			String key = keyPrefix + appKey + ":" + nonce;
46			return redisOps.opsForValue().setIfAbsent(key, "1", ttl)
47					.flatMap(accepted -> {
48						if (Boolean.TRUE.equals(accepted)) {
49							return Mono.empty();
50						}
51						return Mono.error(new JwtAuthenticationException(
52								GatewayAuthErrorCode.REPLAY_DETECTED,
53								"Nonce has already been used: " + nonce));
54					});
55		}
56	}
