3	import org.springframework.boot.autoconfigure.AutoConfiguration;
4	import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
5	import org.springframework.context.annotation.Bean;
6	import org.springframework.data.redis.connection.ReactiveRedisConnectionFactory;
7	import org.springframework.data.redis.core.ReactiveRedisTemplate;
8	import org.springframework.data.redis.serializer.RedisSerializationContext;
9	import org.springframework.data.redis.serializer.StringRedisSerializer;
10	
11	/**
12	 * Provides a {@link ReactiveRedisTemplate} with String serialization
13	 * for simple key/value Redis operations used in gateway state checks.
14	 */
15	@AutoConfiguration
16	@ConditionalOnClass(ReactiveRedisConnectionFactory.class)
17	public class GatewayRedisConfiguration {
18	
19		@Bean
20		ReactiveRedisTemplate<String, String> reactiveStringRedisTemplate(
21				ReactiveRedisConnectionFactory connectionFactory) {
22			RedisSerializationContext<String, String> context = RedisSerializationContext
23					.<String, String>newSerializationContext(StringRedisSerializer.UTF_8)
24					.key(StringRedisSerializer.UTF_8)
25					.value(StringRedisSerializer.UTF_8)
26					.hashKey(StringRedisSerializer.UTF_8)
27					.hashValue(StringRedisSerializer.UTF_8)
28					.build();
29			return new ReactiveRedisTemplate<>(connectionFactory, context);
30		}
31	}
