14	import org.springframework.core.annotation.Order;
15	import org.springframework.http.HttpStatus;
16	import org.springframework.http.MediaType;
17	import org.springframework.stereotype.Component;
18	import org.springframework.web.server.ServerWebExchange;
19	
20	import reactor.core.publisher.Mono;
21	
22	import java.nio.charset.StandardCharsets;
23	
24	/**
25	 * Extracts and validates a JWT Bearer token for routes that require
26	 * JWT authentication. Stores the mapped {@link GatewayPrincipal.User}
27	 * in the exchange for downstream filters and handlers.
28	 */
29	@Component
30	@ConditionalOnProperty("maritime.gateway.security.jwt.enabled")
31	@Order(GatewayFilterOrder.JWT_AUTHENTICATION)
32	public class JwtAuthenticationGatewayFilter implements GlobalFilter, Ordered {
33	
34		private final JwtAuthenticationManager authManager;
35	
36		public JwtAuthenticationGatewayFilter(JwtAuthenticationManager authManager) {
37			this.authManager = authManager;
38		}
39	
40		@Override
41		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
42			RouteSecurityPolicy policy = exchange.getAttribute(RouteSecurityPolicyFilter.POLICY_ATTR);
43			if (!requiresJwt(policy)) {
44				return chain.filter(exchange);
45			}
46	
47			String token = extractBearerToken(exchange);
48			if (token == null || token.isEmpty()) {
49				return writeError(exchange, GatewayAuthErrorCode.MISSING_TOKEN,
50						"Authorization header is missing or does not contain a Bearer token");
51			}
52	
53			return authManager.authenticate(token)
54					.flatMap(principal -> {
55						exchange.getAttributes().put(GatewayPrincipal.ATTRIBUTE, principal);
56						return chain.filter(exchange);
57					})
58					.onErrorResume(JwtAuthenticationException.class,
59							e -> writeError(exchange, e.getErrorCode(), e.getMessage()));
60		}
61	
62		@Override
63		public int getOrder() {
64			return GatewayFilterOrder.JWT_AUTHENTICATION;
65		}
66	
67		private boolean requiresJwt(RouteSecurityPolicy policy) {
68			if (policy == null) {
69				return false;
70			}
71			AuthMode mode = policy.getAuthMode();
72			return mode == AuthMode.JWT || mode == AuthMode.JWT_OR_HMAC || mode == AuthMode.JWT_AND_HMAC;
73		}
74	
75		private String extractBearerToken(ServerWebExchange exchange) {
76			String auth = exchange.getRequest().getHeaders().getFirst("Authorization");
77			if (auth != null && auth.startsWith("Bearer ")) {
78				return auth.substring(7).trim();
79			}
80			return null;
81		}
82	
83		private Mono<Void> writeError(ServerWebExchange exchange, String code, String message) {
84			exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
85			exchange.getResponse().getHeaders().setContentType(MediaType.APPLICATION_JSON);
86			String body = String.format("{\"code\":\"%s\",\"message\":\"%s\"}",
87					escapeJson(code), escapeJson(message));
88			byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
89			return exchange.getResponse()
90					.writeWith(Mono.just(exchange.getResponse().bufferFactory().wrap(bytes)));
91		}
92	
93		private static String escapeJson(String s) {
94			if (s == null) {
95				return "";
96			}
97			return s.replace("\\", "\\\\")
98					.replace("\"", "\\\"")
99					.replace("\n", "\\n")
100					.replace("\r", "\\r")
101					.replace("\t", "\\t");
102		}
103	}
