26	 * Enforces JWT nonce validation for write requests on JWT-protected routes.
27	 * <p>
28	 * Runs after {@link JwtAuthenticationGatewayFilter} so the authenticated
29	 * principal is available. Only enforces nonce for HTTP methods configured
30	 * in {@code maritime.gateway.security.jwt.nonce.required-methods}
31	 * (default: POST, PUT, PATCH, DELETE).
32	 */
33	@Component
34	@ConditionalOnProperty("maritime.gateway.security.jwt.enabled")
35	@Order(GatewayFilterOrder.JWT_NONCE)
36	public class JwtNonceGatewayFilter implements GlobalFilter, Ordered {
37	
38		private final JwtNonceValidator nonceValidator;
39		private final GatewaySecurityProperties properties;
40	
41		public JwtNonceGatewayFilter(JwtNonceValidator nonceValidator,
42				GatewaySecurityProperties properties) {
43			this.nonceValidator = nonceValidator;
44			this.properties = properties;
45		}
46	
47		@Override
48		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
49			if (!properties.getJwt().getNonce().isEnabled()) {
50				return chain.filter(exchange);
51			}
52	
53			RouteSecurityPolicy policy = exchange.getAttribute(RouteSecurityPolicyFilter.POLICY_ATTR);
54			if (!requiresJwt(policy)) {
55				return chain.filter(exchange);
56			}
57	
58			String method = exchange.getRequest().getMethod().name();
59			if (!properties.getJwt().getNonce().getRequiredMethods().contains(method)) {
60				return chain.filter(exchange);
