74			return nonceValidator.validate(principal.sessionId(), nonce)
75					.then(chain.filter(exchange))
76					.onErrorResume(JwtAuthenticationException.class,
77							e -> writeError(exchange, e.getErrorCode(), e.getMessage()));
78		}
