90			return mode == AuthMode.JWT || mode == AuthMode.JWT_OR_HMAC || mode == AuthMode.JWT_AND_HMAC;
91		}
92	
93		private Mono<Void> writeError(ServerWebExchange exchange, String code, String message) {
94			exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
95			exchange.getResponse().getHeaders().setContentType(MediaType.APPLICATION_JSON);
96			String body = String.format("{\"code\":\"%s\",\"message\":\"%s\"}",
97					escapeJson(code), escapeJson(message));
98			byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
99			return exchange.getResponse()
100					.writeWith(Mono.just(exchange.getResponse().bufferFactory().wrap(bytes)));
101		}
