103		private static String escapeJson(String s) {
104			if (s == null) {
105				return "";
106			}
107			return s.replace("\\", "\\\\")
108					.replace("\"", "\\\"")
109					.replace("\n", "\\n")
110					.replace("\r", "\\r")
