11	/**
12	 * Default {@link JwtClaimsMapper} that reads claim values using the
13	 * configurable field names from {@link GatewaySecurityProperties.Claims}.
14	 */
15	@Component
16	@ConditionalOnProperty("maritime.gateway.security.jwt.enabled")
17	public class DefaultJwtClaimsMapper implements JwtClaimsMapper {
18	
19		private final GatewaySecurityProperties.Claims claimsConfig;
20	
21		public DefaultJwtClaimsMapper(GatewaySecurityProperties props) {
22			this.claimsConfig = props.getJwt().getClaims();
23		}
24	
25		@Override
26		public GatewayPrincipal.User map(Claims claims) {
27			var config = claimsConfig;
28			String userId = claims.get(config.getUserId(), String.class);
29			String sessionId = claims.get(config.getSessionId(), String.class);
30			String userName = claims.get(config.getUserName(), String.class);
31			String activeOrgCode = claims.get(config.getActiveOrgCode(), String.class);
32			String activeOrgName = claims.get(config.getActiveOrgName(), String.class);
33			String userSource = claims.get(config.getUserSource(), String.class);
34			String tenantId = claims.get(config.getTenantId(), String.class);
35	
36			List<String> systemScope = resolveSystemScope(claims);
37	
38			return new GatewayPrincipal.User(
39					userId, userName, sessionId,
40					activeOrgCode, activeOrgName,
41					systemScope, userSource, tenantId
42			);
43		}
44	
45		private List<String> resolveSystemScope(Claims claims) {
46			Object value = claims.get(claimsConfig.getSystemScope());
47			if (value instanceof List<?> list) {
48				return list.stream()
49						.filter(obj -> obj instanceof String s && !s.isBlank())
50						.map(obj -> (String) obj)
51						.toList();
52			}
53			if (value instanceof String str && !str.isBlank()) {
54				return List.of(str);
55			}
56			return List.of();
57		}
58	}
