2	
3	import com.maritime.platform.gateway.security.GatewaySecurityProperties;
4	import com.maritime.platform.gateway.security.jwt.GatewayAuthErrorCode;
5	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationException;
6	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
7	import org.springframework.data.redis.core.ReactiveRedisOperations;
8	import org.springframework.stereotype.Component;
9	import reactor.core.publisher.Mono;
10	
11	import java.time.Duration;
12	
13	/**
14	 * Validates JWT request nonces using Redis SETNX with TTL to prevent
15	 * replay attacks on write operations.
16	 *
17	 * <p>The atomic {@code SET key value NX EX ttl} ensures that even under
18	 * concurrent requests, only the first write succeeds and subsequent
19	 * attempts are correctly detected as replays.
20	 */
21	@Component
22	@ConditionalOnProperty("maritime.gateway.security.jwt.enabled")
23	public class JwtNonceValidator {
24	
25		private final ReactiveRedisOperations<String, String> redisOps;
26		private final String keyPrefix;
27		private final Duration ttl;
28	
29		public JwtNonceValidator(ReactiveRedisOperations<String, String> redisOps,
30				GatewaySecurityProperties properties) {
31			this.redisOps = redisOps;
32			GatewaySecurityProperties.JwtNonce nonce = properties.getJwt().getNonce();
33			this.keyPrefix = nonce.getSimpleKeyPrefix();
34			this.ttl = nonce.getTtl();
35		}
36	
37		/**
38		 * Validate that the nonce has not been used before for this session.
39		 * Uses atomic Redis SETNX with TTL.
40		 *
41		 * @param sessionId the session ID from the authenticated principal
42		 * @param nonce     the nonce value from the X-Nonce header
43		 * @return empty Mono on success, error with REPLAY_DETECTED if nonce was already used
44		 */
45		public Mono<Void> validate(String sessionId, String nonce) {
46			String key = keyPrefix + sessionId + ":" + nonce;
47			return redisOps.opsForValue().setIfAbsent(key, "1", ttl)
48					.flatMap(accepted -> {
49						if (Boolean.TRUE.equals(accepted)) {
50							return Mono.empty();
51						}
52						return Mono.error(new JwtAuthenticationException(
53								GatewayAuthErrorCode.REPLAY_DETECTED,
54								"Nonce has already been used: " + nonce));
55					});
56		}
57	}
