67		/**
68		 * Builds a valid HMAC signature for POST /api/data with the given inputs.
69		 */
70		private String sign(String timestamp, String nonce, byte[] bodyBytes) {
71			return sign("POST", "/api/data", timestamp, nonce, bodyBytes);
72		}
