74		private String sign(String method, String path, String timestamp, String nonce, byte[] bodyBytes) {
75			String bodyDigest = HmacAuthenticationManager.sha256Hex(bodyBytes);
76			String canonical = canonicalBuilder.build(APP_KEY, method, path,
77					null, timestamp, nonce, bodyDigest);
78			return HmacAuthenticationManager.hmacSha256Hex(APP_SECRET, canonical);
79		}
