159			try {
160				return HEX.formatHex(MessageDigest.getInstance("SHA-256").digest(data));
161			} catch (java.security.NoSuchAlgorithmException e) {
162				throw new RuntimeException("SHA-256 algorithm not available", e);
163			}
164		}
