		if (Math.abs(now - ts) > tolerance.toMillis()) {
			return Mono.error(new JwtAuthenticationException(
					GatewayAuthErrorCode.TIMESTAMP_EXPIRED,
					"Timestamp is outside the allowed tolerance window"));
		}

