					});
		}
	}

	// ---------- No Redis ----------

	@Nested
	@DisplayName("Without Redis")
	class WithoutRedis {

		@Test
		@DisplayName("resolves from config directly when Redis is unavailable")
		void resolvesFromConfigWhenNoRedis() {
